import SwiftUI

/// Per-project settings (issue #7): the run command + whether it auto-runs after a workroom is
/// created. Opened from the project row's context menu. Uses a draft + Cancel/Save model (unlike the
/// app `SettingsView`, which writes live) because a run command is a deliberate value you may get
/// wrong mid-typing. Styled like `SettingsView` (grouped form, fixed width) so it feels native.
struct ProjectSettingsSheet: View {
  let project: Project
  /// True when opened because Run was invoked with no command configured (issue #127) — shows a
  /// warning explaining why nothing started. False (default) for the plain "Project Settings…"
  /// entry points, which need no explanation.
  var showsRunWarning: Bool = false
  @EnvironmentObject var store: AppStore
  @Environment(\.dismiss) private var dismiss

  // Draft state, seeded from the store on appear; committed only on Save.
  @State private var command = ""
  @State private var autoRun = false

  /// Trim with the same set `RunConfig.hasCommand` uses, so the auto-run gate and what's actually
  /// runnable agree (a newlines-only command must read as blank too — review #7).
  private var commandIsBlank: Bool {
    command.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
  }

  var body: some View {
    VStack(spacing: 0) {
      Form {
        Section {
          if showsRunWarning {
            Label(
              "No run command is defined yet — you can't run this workroom until you set one.",
              systemImage: "exclamationmark.triangle.fill"
            )
            .foregroundStyle(.orange)
            // Stable identifier so the XCUITest doesn't match on the exact warning string
            // (fragile: an em dash, wording that may change) — added after outside-voice review
            // flagged the risk.
            .accessibilityIdentifier("projectSettings.runWarning")
          }
          TextField("Run command", text: $command, prompt: Text("e.g. npm run dev"))
            .lineLimit(1)
            .accessibilityIdentifier("projectSettings.runCommand")
          Toggle("Run automatically when a workroom is created", isOn: $autoRun)
            // Disabled — and forced back off — when there's no command, so Save can't persist a dead
            // `RunConfig(command: "", autoRun: true)` that never runs (review #7).
            .disabled(commandIsBlank)
            .onChange(of: command) { _ in if commandIsBlank { autoRun = false } }
            .accessibilityIdentifier("projectSettings.autoRun")
        } header: {
          Text("Run Command")
        } footer: {
          Text(
            "Runs in a dedicated terminal at the workroom's directory, in your login shell. "
              + "Start it from the toolbar Run button or ⌘R.")
        }
      }
      .formStyle(.grouped)

      Divider()
      HStack {
        Spacer()
        Button("Cancel") { dismiss() }
          .keyboardShortcut(.cancelAction)
        Button("Save") {
          store.setRunConfig(
            RunConfig(command: command, autoRun: autoRun), forProject: project.path)
          dismiss()
        }
        .keyboardShortcut(.defaultAction)
        .buttonStyle(.borderedProminent)
      }
      .padding()
    }
    .frame(width: 460)
    .onAppear {
      let config = store.runConfig(forProject: project.path)
      command = config.command
      autoRun = config.autoRun
    }
  }
}

/// A workroom awaiting a display-label edit (issue #41). Held on the store (and `Identifiable` so it
/// drives a `.sheet(item:)`) so the sidebar row's and tab chip's "Set/Edit Label…" items share one
/// piece of state. `id` is the workroom's project-scoped target id, so re-targeting a different
/// workroom rebuilds the sheet (resetting its typed `@State`).
struct PendingWorkroomLabel: Identifiable {
  let workroom: Workroom
  let project: Project
  var id: String { TerminalTarget.workroomID(project: project.path, name: workroom.name) }
}

/// The project-settings sheet's one presentation source (issue #127): used both by the plain
/// "Project Settings…" entry points (hover button / context menu — `showsRunWarning: false`) and
/// by Run invoked with no command configured (`showsRunWarning: true`). Unified into ONE
/// store-level pending state — not one local to `ProjectSidebar` plus a second store-level one —
/// because ⌘R is a global key monitor that can fire while the sheet is already open from the other
/// entry point; two independent `.sheet(item:)` presenters would race (eng review issue #127-eng-1).
struct PendingProjectSettings: Identifiable {
  let project: Project
  var showsRunWarning: Bool = false
  var id: String { project.id }
}

/// App-wide state and actions. A single shared instance is used so the App, views,
/// and menu Commands all act on the same store. All CLI work is awaited (it runs off
/// the main thread inside WorkroomCLI), keeping the UI responsive.
@MainActor
final class AppStore: ObservableObject {
  /// Shared, app-wide project data (issue #70). Holds the project list and everything derived from
  /// it that is identical across windows (root labels, VCS/CI status cache, GitHub-CLI status, busy
  /// set). The properties below proxy through to it, and `init` re-publishes its `objectWillChange`,
  /// so views/menus observing this store still re-render when the shared data changes.
  let projectStore: ProjectStore
  private var projectStoreObservation: AnyCancellable?

  /// Seam over the bundled `workroom` CLI (issue #103). Production uses
  /// `WorkroomCLI.shared`; tests inject a fake to drive mutations without a real
  /// subprocess. Injected like `projectStore` (in the init body, not as a default
  /// arg, which is evaluated nonisolated).
